/// Writes values in the format of Flutter's standard message codec.
///
/// Implemented against Foundation rather than `FlutterStandardWriter` so that
/// swiftgen can compile this file without importing Flutter.
private struct ClipboardApiPigeonInteropWriter {
  private(set) var bytes: [UInt8] = []

  mutating func writeByte(_ byte: UInt8) {
    bytes.append(byte)
  }

  mutating func writeRaw<T: FixedWidthInteger>(_ value: T) {
    withUnsafeBytes(of: value.littleEndian) { bytes.append(contentsOf: $0) }
  }

  mutating func writeSize(_ size: Int) {
    if size < Int(ClipboardApiPigeonInteropCodec.sizeUInt16) {
      writeByte(UInt8(size))
    } else if size <= Int(UInt16.max) {
      writeByte(ClipboardApiPigeonInteropCodec.sizeUInt16)
      writeRaw(UInt16(size))
    } else {
      writeByte(ClipboardApiPigeonInteropCodec.sizeUInt32)
      writeRaw(UInt32(size))
    }
  }

  mutating func writeAlignment(_ alignment: Int) {
    let mod = bytes.count % alignment
    if mod != 0 {
      bytes.append(contentsOf: repeatElement(0, count: alignment - mod))
    }
  }

  mutating func writeTypedData<T>(_ type: UInt8, _ array: [T], alignment: Int) {
    writeByte(type)
    writeSize(array.count)
    writeAlignment(alignment)
    array.withUnsafeBytes { bytes.append(contentsOf: $0) }
  }

  mutating func writeTypedData<T>(_ type: UInt8, _ array: [T]?, alignment: Int) {
    guard let array = array else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    writeTypedData(type, array, alignment: alignment)
  }

  mutating func writeString(_ string: String) {
    writeByte(ClipboardApiPigeonInteropCodec.typeString)
    var string = string
    string.withUTF8 { utf8 in
      writeSize(utf8.count)
      bytes.append(contentsOf: utf8)
    }
  }

  mutating func writeData(_ data: Foundation.Data) {
    writeByte(ClipboardApiPigeonInteropCodec.typeUint8List)
    writeSize(data.count)
    bytes.append(contentsOf: data)
  }

  mutating func writeValue(_ value: Any?) {
    guard let value = value else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    // The most common types are matched by exact type first, because
    // comparing metatypes is much cheaper than dynamic casts.
    let valueType = Swift.type(of: value)
    if valueType == String.self {
      writeString(value as! String)
      return
    }
    if valueType == Int64.self {
      writeByte(ClipboardApiPigeonInteropCodec.typeInt64)
      writeRaw(value as! Int64)
      return
    }
    if valueType == Bool.self {
      writeByte((value as! Bool) ? ClipboardApiPigeonInteropCodec.typeTrue : ClipboardApiPigeonInteropCodec.typeFalse)
      return
    }
    if valueType == Double.self {
      writeByte(ClipboardApiPigeonInteropCodec.typeFloat64)
      writeAlignment(8)
      writeRaw((value as! Double).bitPattern)
      return
    }
    if valueType == [Any?].self {
      writeList(value as! [Any?])
      return
    }
    if writeCustomValue(value, type: valueType) {
      return
    }
    // Typed data is matched by exact type, because casting an empty array of
    // any element type to an array of numbers succeeds.
    if valueType == [UInt8].self {
      writeTypedData(ClipboardApiPigeonInteropCodec.typeUint8List, value as! [UInt8], alignment: 1)
      return
    }
    if valueType == [Int32].self {
      writeTypedData(ClipboardApiPigeonInteropCodec.typeInt32List, value as! [Int32], alignment: 4)
      return
    }
    if valueType == [Int64].self {
      writeTypedData(ClipboardApiPigeonInteropCodec.typeInt64List, value as! [Int64], alignment: 8)
      return
    }
    if valueType == [Float64].self {
      writeTypedData(ClipboardApiPigeonInteropCodec.typeFloat64List, value as! [Float64], alignment: 8)
      return
    }
    if valueType == [Float32].self {
      writeTypedData(ClipboardApiPigeonInteropCodec.typeFloat32List, value as! [Float32], alignment: 4)
      return
    }
    if valueType == AnyHashable.self {
      writeValue((value as! AnyHashable).base)
      return
    }
    if valueType == Foundation.Data.self {
      writeData(value as! Foundation.Data)
      return
    }
    // Collections are matched by protocol before any cast to a class, such as
    // `NSNumber`, because those casts can bridge a whole Swift collection to
    // Objective-C just to fail.
    if let list = value as? ClipboardApiPigeonInteropList {
      list.pigeonWrite(to: &self)
      return
    }
    if let map = value as? ClipboardApiPigeonInteropMap {
      map.pigeonWrite(to: &self)
      return
    }
    if let optional = value as? ClipboardApiPigeonInteropOptional {
      writeValue(optional.pigeonWrapped)
      return
    }
    if ClipboardApiPigeonInternal.isNullish(value) {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    if let number = value as? NSNumber {
      if CFGetTypeID(number) == CFBooleanGetTypeID() {
        writeByte(number.boolValue ? ClipboardApiPigeonInteropCodec.typeTrue : ClipboardApiPigeonInteropCodec.typeFalse)
      } else if CFNumberIsFloatType(number) {
        writeByte(ClipboardApiPigeonInteropCodec.typeFloat64)
        writeAlignment(8)
        writeRaw(number.doubleValue.bitPattern)
      } else {
        writeByte(ClipboardApiPigeonInteropCodec.typeInt64)
        writeRaw(number.int64Value)
      }
      return
    }
    if let string = value as? String {
      writeString(string)
      return
    }
    if let data = value as? Foundation.Data {
      writeData(data)
      return
    }
    if let array = value as? NSArray {
      writeByte(ClipboardApiPigeonInteropCodec.typeList)
      writeSize(array.count)
      for item in array {
        writeValue(item)
      }
      return
    }
    if let dictionary = value as? NSDictionary {
      writeByte(ClipboardApiPigeonInteropCodec.typeMap)
      writeSize(dictionary.count)
      for (key, item) in dictionary {
        writeValue(key)
        writeValue(item)
      }
      return
    }
    if writeCustomValueFallback(value) {
      return
    }
    preconditionFailure("Unsupported value: \(value) of type \(valueType)")
  }

  mutating func writeList(_ list: [Any?]) {
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(list.count)
    for item in list {
      writeValue(item)
    }
  }

  mutating func writeList<T>(_ list: [T]?) {
    guard let list = list else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(list.count)
    for item in list {
      writeValue(item)
    }
  }

  mutating func writeList<T>(_ list: [T?]?) {
    guard let list = list else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(list.count)
    for item in list {
      writeOptional(item)
    }
  }

  mutating func writeList<T>(_ list: [T]?, _ writeElement: (inout Self, T) -> Void) {
    guard let list = list else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(list.count)
    for item in list {
      writeElement(&self, item)
    }
  }

  mutating func writeOptional<T>(_ value: T?) {
    if let value = value {
      writeValue(value)
    } else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
    }
  }

  mutating func writeMap<K, V>(_ map: [K: V]?) {
    guard let map = map else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(ClipboardApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeValue(key)
      writeValue(item)
    }
  }

  mutating func writeMap<K, V>(_ map: [K?: V]?) {
    guard let map = map else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(ClipboardApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeOptional(key)
      writeValue(item)
    }
  }

  mutating func writeMap<K, V>(_ map: [K: V?]?) {
    guard let map = map else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(ClipboardApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeValue(key)
      writeOptional(item)
    }
  }

  mutating func writeMap<K, V>(_ map: [K?: V?]?) {
    guard let map = map else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(ClipboardApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeOptional(key)
      writeOptional(item)
    }
  }

  mutating func writeMap<K, V>(_ map: [K: V]?, _ writeEntry: (inout Self, K, V) -> Void) {
    guard let map = map else {
      writeByte(ClipboardApiPigeonInteropCodec.typeNull)
      return
    }
    writeByte(ClipboardApiPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeEntry(&self, key, item)
    }
  }


  mutating func writeWireClipboardBufferTarget(_ value: WireClipboardBufferTarget) {
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(2)
    writeValue(value.buffer)
    writeValue(value.customBufferName)
  }

  mutating func writeWireCustomFormatEntry(_ value: WireCustomFormatEntry) {
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(2)
    writeValue(value.format)
