  }

  mutating func writeWireClipboardItem(_ value: WireClipboardItem) {
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(11)
    writeValue(value.plainText)
    writeValue(value.html)
    writeTypedData(ClipboardApiPigeonInteropCodec.typeUint8List, value.rtfBytes, alignment: 1)
    writeValue(value.markdown)
    writeValue(value.uri)
    writeTypedData(ClipboardApiPigeonInteropCodec.typeUint8List, value.imageBytes, alignment: 1)
    writeValue(value.imageMimeType)
    writeList(value.files)
    writeValue(value.fileCopyMode)
    writeValue(value.colorValue)
    writeList(value.customFormats)
  }

  mutating func writeWireClipboardWriteOptions(_ value: WireClipboardWriteOptions) {
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(7)
    writeValue(value.buffer)
    writeValue(value.customBufferName)
    writeValue(value.isSensitive)
    writeValue(value.isTransient)
    writeValue(value.localOnly)
    writeValue(value.expirationMs)
    writeValue(value.label)
  }

  mutating func writeWireClipboardReadOptions(_ value: WireClipboardReadOptions) {
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(5)
    writeValue(value.buffer)
    writeValue(value.customBufferName)
    writeValue(value.preferredImageFormat)
    writeList(value.requestedCustomFormats)
    writeValue(value.targetFormat)
  }

  mutating func writeWireClipboardMetadata(_ value: WireClipboardMetadata) {
    writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writeSize(13)
    writeValue(value.changeCount)
    writeValue(value.timestampMs)
    writeValue(value.itemCount)
    writeValue(value.hasPlainText)
    writeValue(value.hasHtml)
    writeValue(value.hasRtf)
    writeValue(value.hasMarkdown)
    writeValue(value.hasUri)
    writeValue(value.hasImage)
    writeValue(value.hasFiles)
    writeValue(value.hasColor)
