  mutating func writeCustomValue(_ value: Any, type valueType: Any.Type) -> Bool {
    if valueType == WireClipboardBuffer.self {
      writeByte(129)
      writeValue(Int64((value as! WireClipboardBuffer).rawValue))
      return true
    }
    if valueType == WireFileCopyMode.self {
      writeByte(130)
      writeValue(Int64((value as! WireFileCopyMode).rawValue))
      return true
    }
    if valueType == WireClipboardDetectedPattern.self {
      writeByte(131)
      writeValue(Int64((value as! WireClipboardDetectedPattern).rawValue))
      return true
    }
    if valueType == WireClipboardBufferTarget.self {
      writeByte(132)
      writeWireClipboardBufferTarget((value as! WireClipboardBufferTarget))
      return true
    }
    if valueType == WireCustomFormatEntry.self {
      writeByte(133)
      writeWireCustomFormatEntry((value as! WireCustomFormatEntry))
      return true
    }
    if valueType == WireClipboardItem.self {
      writeByte(134)
      writeWireClipboardItem((value as! WireClipboardItem))
      return true
    }
    if valueType == WireClipboardWriteOptions.self {
      writeByte(135)
      writeWireClipboardWriteOptions((value as! WireClipboardWriteOptions))
      return true
    }
    if valueType == WireClipboardReadOptions.self {
      writeByte(136)
      writeWireClipboardReadOptions((value as! WireClipboardReadOptions))
      return true
    }
    if valueType == WireClipboardMetadata.self {
      writeByte(137)
      writeWireClipboardMetadata((value as! WireClipboardMetadata))
      return true
    }
    if valueType == WireClipboardChangeEvent.self {
      writeByte(138)
      writeWireClipboardChangeEvent((value as! WireClipboardChangeEvent))
      return true
    }
    return false
  }

  mutating func writeCustomValueFallback(_ value: Any) -> Bool {
    if let value = value as? WireClipboardBuffer {
      writeByte(129)
      writeValue(Int64(value.rawValue))
      return true
    }
    if let value = value as? WireFileCopyMode {
      writeByte(130)
      writeValue(Int64(value.rawValue))
      return true
    }
    if let value = value as? WireClipboardDetectedPattern {
      writeByte(131)
      writeValue(Int64(value.rawValue))
      return true
    }
    if let value = value as? WireClipboardBufferTarget {
      writeByte(132)
      writeWireClipboardBufferTarget(value)
      return true
    }
    if let value = value as? WireCustomFormatEntry {
      writeByte(133)
      writeWireCustomFormatEntry(value)
      return true
    }
    if let value = value as? WireClipboardItem {
      writeByte(134)
