  }
}

/// Writes typed lists without converting them to `[Any?]` first.
private protocol ClipboardApiPigeonInteropList {
  func pigeonWrite(to writer: inout ClipboardApiPigeonInteropWriter)
}

extension Array: ClipboardApiPigeonInteropList {
  fileprivate func pigeonWrite(to writer: inout ClipboardApiPigeonInteropWriter) {
    writer.writeByte(ClipboardApiPigeonInteropCodec.typeList)
    writer.writeSize(count)
    for item in self {
      writer.writeValue(item)
